// Follow-up e mensagem nao solicitada: fora de hora ela irrita em vez de
// recuperar o lead. Este node e o unico lugar que decide se a rodada roda.
const cfg = $('Config Follow-up').first().json;
const tz = cfg.timezone || 'America/Sao_Paulo';

const num = (v, padrao) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : padrao;
};

const inicio = num(cfg.horario_inicio, 8);
const fim = num(cfg.horario_fim, 20);
const dias = String(cfg.dias_semana || '1,2,3,4,5,6')
  .split(',')
  .map((s) => Number(s.trim()))
  .filter((n) => Number.isFinite(n));

// weekday no Luxon: 1 = segunda ... 7 = domingo
const agora = $now.setZone(tz);

// O fim e inclusivo no minuto cravado: a rodada das 20:00 precisa acontecer,
// porque e nela que sai o follow-up que venceria durante a madrugada. Das
// 20:01 em diante, nada mais sai.
const dentro = dias.includes(agora.weekday)
  && agora.hour >= inicio
  && (agora.hour < fim || (agora.hour === fim && agora.minute === 0));

return [{
  json: {
    dentro,
    agora: agora.toISO(),
    hora: agora.hour,
    dia_semana: agora.weekday,
    janela: inicio + 'h-' + fim + 'h (' + tz + ')',
  },
}];

// O endpoint de conversas do Chatwoot devolve 25 por pagina e ignora per_page.
// Para varrer mais que isso a unica saida e pedir pagina por pagina.
const cfg = $('Config Follow-up').first().json;
const total = Math.max(1, Math.min(Number(cfg.chatwoot_paginas) || 1, 20));
const status = String(cfg.chatwoot_status || 'open').trim() || 'open';

const paginas = [];
for (let p = 1; p <= total; p++) {
  paginas.push({
    json: {
      url: cfg.chatwoot_url.replace(/\/+$/, '')
        + '/api/v1/accounts/' + cfg.chatwoot_account_id
        + '/conversations?status=' + encodeURIComponent(status)
        + '&assignee_type=all&page=' + p,
      pagina: p,
    },
  });
}
return paginas;

// Normaliza o que veio do Chatwoot numa lista simples de conversas que a Isis
// atende, ja com o canal e a chave de pausa resolvidos. O formato da resposta
// mudou entre versoes do Chatwoot, por isso a leitura e defensiva.
const cfg = $('Config Follow-up').first().json;
const inboxWa = String(cfg.inbox_whatsapp_id || '').trim();
const inboxSite = String(cfg.inbox_site_id || '').trim();
const limite = Number(cfg.limite_conversas) || 100;

// Chatwoot e Evolution guardam o numero com DDI. Sem o 55 a chave de pausa nao
// bate com o remoteJid e a Isis falaria por cima do corretor.
const comDDI = (n) => (n.length === 10 || n.length === 11) ? '55' + n : n;

const brutas = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const lista = (j.data && (j.data.payload || j.data.conversations))
    || j.payload
    || j.conversations
    || (Array.isArray(j.data) ? j.data : null)
    || [];
  for (const c of lista) brutas.push(c && c.conversation ? c.conversation : c);
}

const vistos = new Set();
const saida = [];

for (const c of brutas) {
  if (!c) continue;
  const id = String(c.id || '');
  if (!id || vistos.has(id)) continue;
  vistos.add(id);

  const meta = c.meta || {};
  const contato = meta.sender || c.contact || {};
  const telefone = comDDI(String(contato.phone_number || '').replace(/\D/g, ''));
  const inbox = String(c.inbox_id || (meta.channel_id || '') || '');

  // Com os ids de inbox preenchidos, o canal e explicito. Sem eles, cai no
  // criterio que sempre vale: quem tem telefone veio do WhatsApp.
  let canal;
  if (inboxWa || inboxSite) {
    if (inboxWa && inbox === inboxWa) canal = 'whatsapp';
    else if (inboxSite && inbox === inboxSite) canal = 'site';
    else continue;  // inbox que nao e da Isis
  } else {
    canal = telefone ? 'whatsapp' : 'site';
  }

  // Sem numero nao ha para onde mandar mensagem no WhatsApp.
  if (canal === 'whatsapp' && !telefone) continue;

  const remote_jid = telefone ? telefone + '@s.whatsapp.net' : '';
  const block_key = canal === 'site'
    ? 'site_' + id + '_block'
    : remote_jid + '_block';

  saida.push({
    json: {
      conversation_id: id,
      inbox_id: inbox,
      canal,
      status: c.status || '',
      nome: contato.name || contato.email || 'Visitante do site',
      telefone,
      remote_jid,
      block_key,
    },
  });

  if (saida.length >= limite) break;
}

return saida;

// O cerebro do agente. Le a conversa inteira, descobre quem falou por ultimo e
// ha quantas horas, cruza com os follow-ups ja enviados e devolve uma acao:
//
//   followup -> a Isis perguntou algo e o lead sumiu: cutucar
//   alerta   -> o lead perguntou algo e ninguem respondeu: avisar o corretor
//   nada     -> nao ha o que fazer nesta conversa agora
const cfg = $('Config Follow-up').first().json;
const conv = $('Loop Conversas').first().json;
const tz = cfg.timezone || 'America/Sao_Paulo';
const cfgBot = String(cfg.bot_agent_id || '').trim();

const num = (v, padrao) => {
  const n = Number(v);
  return Number.isFinite(n) ? n : padrao;
};

// ---------- 1. mensagens ----------
let brutas = [];
try {
  const r = $('Lê Mensagens').first().json || {};
  brutas = r.payload || r.messages
    || (r.data && (r.data.payload || r.data.messages))
    || (Array.isArray(r.data) ? r.data : null)
    || [];
} catch (e) {
  brutas = [];
}
if (!Array.isArray(brutas)) brutas = [];

// message_type chega como numero na API (0 incoming, 1 outgoing, 2 activity,
// 3 template) e como texto no webhook. Aceitamos as duas formas.
const tipoDe = (m) => {
  const t = m.message_type;
  if (t === 0 || t === '0' || t === 'incoming') return 'incoming';
  if (t === 1 || t === '1' || t === 'outgoing') return 'outgoing';
  return 'outro';
};

// A Isis e o corretor chegam os dois como outgoing. Ela assina as proprias
// mensagens com content_attributes.isis_bot — e essa assinatura que separa.
const ehDaIsis = (m) => {
  const attrs = m.content_attributes || {};
  if (attrs.isis_bot === true) return true;
  const sender = m.sender || {};
  if (String(sender.type || '').toLowerCase() === 'agent_bot') return true;
  if (cfgBot && String(sender.id || '') === cfgBot) return true;
  return false;
};

const quando = (m) => {
  const t = m.created_at;
  if (typeof t === 'number') return new Date(t * 1000);
  const n = Number(t);
  if (Number.isFinite(n) && n > 0) return new Date(n * 1000);
  return new Date(t);
};

const msgs = [];
for (const m of brutas) {
  if (!m || m.private === true) continue;
  const tipo = tipoDe(m);
  if (tipo === 'outro') continue;
  const texto = String(m.content || '').trim();
  if (!texto) continue;
  const at = quando(m);
  if (!(at instanceof Date) || isNaN(at.getTime())) continue;
  msgs.push({
    quem: tipo === 'incoming' ? 'lead' : (ehDaIsis(m) ? 'isis' : 'corretor'),
    at,
    texto,
  });
}
msgs.sort((a, b) => a.at - b.at);

const nada = (motivo) => [{
  json: {
    acao: 'nada',
    motivo,
    conversation_id: conv.conversation_id,
    canal: conv.canal,
  },
}];

if (msgs.length === 0) return nada('conversa sem mensagens de texto');

const ultima = msgs[msgs.length - 1];
const ultimaDoLead = [...msgs].reverse().find((m) => m.quem === 'lead') || null;

// Relogio do servidor vs. do Chatwoot pode divergir alguns segundos.
const horas = Math.max(0, (Date.now() - ultima.at.getTime()) / 3600000);
const horasRed = Math.round(horas * 10) / 10;

// ---------- 2. o que ja fizemos aqui ----------
const enviados = [];
let ultimoAlerta = null;
for (const item of $input.all()) {
  const r = item.json || {};
  if (!r.created_at) continue;
  const at = new Date(r.created_at);
  if (isNaN(at.getTime())) continue;
  if (r.status === 'alerta') {
    if (!ultimoAlerta || at > ultimoAlerta) ultimoAlerta = at;
  } else {
    const anc = r.ancora_em ? new Date(r.ancora_em) : null;
    enviados.push({
      etapa: Number(r.etapa) || 0,
      at,
      ancora: (anc && !isNaN(anc.getTime())) ? anc : null,
    });
  }
}

// Se o lead voltou a falar, a cadencia anterior morreu: so contam os
// follow-ups enviados depois da ultima fala dele.
const corte = ultimaDoLead ? ultimaDoLead.at.getTime() : 0;
const sequencia = enviados.filter((e) => e.at.getTime() > corte);
const ultimaEtapa = sequencia.reduce((max, e) => Math.max(max, e.etapa), 0);

// ---------- 3. a ancora da cadencia ----------
// As horas contam sempre da mensagem que ficou sem resposta — nunca do ultimo
// follow-up. Se contassem do follow-up, cada cutucada empurraria a proxima
// para frente e a sequencia inteira escorregaria para a madrugada.
// O primeiro follow-up da sequencia grava a ancora; os seguintes reusam ela.
let ancora = ultima.at;
const comAncora = sequencia.filter((e) => e.ancora).sort((a, b) => b.at - a.at);
if (comAncora.length) ancora = comAncora[0].ancora;

const horasAncora = Math.max(0, (Date.now() - ancora.getTime()) / 3600000);

// ---------- 4. contexto para o redator ----------
const rotulo = { lead: 'Lead', isis: 'Isis', corretor: 'Corretor' };
const historico = msgs.slice(-20).map((m) =>
  rotulo[m.quem] + ' (' + m.at.toLocaleString('pt-BR', { timeZone: tz }) + '): ' + m.texto
).join('\n');

const base = {
  conversation_id: conv.conversation_id,
  canal: conv.canal,
  nome: conv.nome,
  telefone: conv.telefone,
  remote_jid: conv.remote_jid,
  block_key: conv.block_key,
  horas: horasRed,
  horas_ancora: Math.round(horasAncora * 10) / 10,
  ancora_em: ancora.toISOString(),
  ultima_de: ultima.quem,
  ultima_em: ultima.at.toISOString(),
  historico,
  total_mensagens: msgs.length,
};

// ---------- 5. decisao ----------
const maxHoras = num(cfg.max_horas_conversa, 336);
if (horas > maxHoras) {
  return nada('conversa parada ha ' + horasRed + 'h, acima do limite de ' + maxHoras + 'h');
}

// O corretor falou por ultimo: o lead e dele agora. A Isis nao cutuca por cima
// de um humano — e a mesma regra que vale no resto do fluxo.
if (ultima.quem === 'corretor') {
  return nada('corretor falou por ultimo e esta com a conversa');
}

// O lead perguntou e ninguem respondeu. Nao e caso de follow-up: e caso de
// avisar quem deveria ter respondido.
if (ultima.quem === 'lead') {
  const alertaHoras = num(cfg.alerta_corretor_horas, 0);
  if (alertaHoras <= 0) return nada('lead aguardando resposta; alerta desativado');
  if (horas < alertaHoras) {
    return nada('lead aguardando ha ' + horasRed + 'h, abaixo das ' + alertaHoras + 'h');
  }
  if (ultimoAlerta && ultimoAlerta >= ultima.at) {
    return nada('alerta ja registrado para esta mensagem do lead');
  }
  return [{ json: { ...base, acao: 'alerta', etapa: 0 } }];
}

// ultima.quem === 'isis': a pergunta ficou no ar. Este e o caso de follow-up.
const etapas = String(cfg.etapas_horas || '3,8,12')
  .split(',')
  .map((s) => Number(s.trim()))
  .filter((n) => Number.isFinite(n) && n > 0)
  .sort((a, b) => a - b);

if (etapas.length === 0) return nada('nenhuma etapa configurada em etapas_horas');

// As etapas sao horas acumuladas desde a ancora, nao intervalos entre
// follow-ups: 3,8,12 com o lead parando as 08h da 11h, 16h e 20h.
const proxima = ultimaEtapa + 1;
if (proxima > etapas.length) {
  return nada('cadencia completa (' + etapas.length + ' follow-ups); nao insiste mais');
}

const venceEm = ancora.getTime() + etapas[proxima - 1] * 3600000;

// Quando a janela comercial atrasa uma etapa, as seguintes nao podem se
// amontoar logo atras dela: cada uma respeita tambem o intervalo que a cadencia
// previa entre ela e a anterior. Sem isso, um lead que ficou em silencio a
// noite toda receberia as tres cutucadas em rodadas seguidas, de 30 em 30 min.
let minimo = venceEm;
if (ultimaEtapa > 0 && sequencia.length) {
  const ultimoEnvio = sequencia.reduce((m, e) => Math.max(m, e.at.getTime()), 0);
  const intervalo = (etapas[proxima - 1] - etapas[ultimaEtapa - 1]) * 3600000;
  minimo = Math.max(venceEm, ultimoEnvio + intervalo);
}

// Perto de fechar, uma etapa que so venceria de madrugada e puxada para agora.
// E o que evita a cadencia inteira escorregar para o dia seguinte por causa de
// algumas horas de diferenca.
const inicioH = num(cfg.horario_inicio, 8);
const fimH = num(cfg.horario_fim, 20);
const antecipacaoMin = num(cfg.antecipacao_minutos, 5);
const diasUteis = String(cfg.dias_semana || '1,2,3,4,5,6')
  .split(',')
  .map((s) => Number(s.trim()))
  .filter((n) => Number.isFinite(n));

const agoraTz = $now.setZone(tz);
const fechamento = agoraTz.set({ hour: fimH, minute: 0, second: 0, millisecond: 0 });

// Proxima abertura: amanha no horario de inicio, pulando os dias nao uteis.
let abertura = agoraTz.plus({ days: 1 }).set({ hour: inicioH, minute: 0, second: 0, millisecond: 0 });
for (let i = 0; i < 8 && diasUteis.length && !diasUteis.includes(abertura.weekday); i++) {
  abertura = abertura.plus({ days: 1 });
}

// antecipacao_minutos e so tolerancia para a rodada nao cair cravada nas 20:00
// (reinicio do n8n, atraso do scheduler). Negativo desliga a antecipacao, e ai
// o follow-up da madrugada espera a abertura do dia seguinte.
const minutosAteFechar = fechamento.diff(agoraTz, 'minutes').minutes;
const naBocaDoFechamento = antecipacaoMin >= 0
  && minutosAteFechar >= 0
  && minutosAteFechar <= antecipacaoMin;

let antecipada = false;

if (Date.now() < minimo) {
  // Ainda nao venceu. Unica excecao: vence durante a madrugada e estamos na
  // ultima rodada do dia — nesse caso sai agora, no fechamento.
  // O que vence as 20:00 cravadas nao entra aqui: sai pela rodada das 20:00.
  const cabeNaMadrugada = minimo > fechamento.toMillis() && minimo < abertura.toMillis();
  if (!(naBocaDoFechamento && cabeNaMadrugada)) {
    const falta = Math.round(((minimo - Date.now()) / 3600000) * 10) / 10;
    return nada('etapa ' + proxima + ' (' + etapas[proxima - 1] + 'h de silencio) vence em ' + falta + 'h');
  }
  antecipada = true;
}

return [{
  json: {
    ...base,
    acao: 'followup',
    etapa: proxima,
    total_etapas: etapas.length,
    etapa_anterior: ultimaEtapa,
    janela_horas: etapas[proxima - 1],
    vence_em: new Date(minimo).toISOString(),
    antecipada,
  },
}];

// O modelo as vezes devolve a frase entre aspas, prefixada com "Isis:" ou com
// um paragrafo de explicacao junto. Aqui fica so o que vai para o lead — e, se
// nada sobrar, um texto de reserva, para a rodada nunca enviar mensagem vazia.
const d = $('Decide Follow-up').first().json;

let txt = String($json.output ?? $json.text ?? '').trim();
txt = txt.replace(/^```[a-z]*\s*/i, '').replace(/```$/, '').trim();
txt = txt.replace(/^["'`“”]+|["'`“”]+$/g, '').trim();
txt = txt.replace(/^Isis\s*:\s*/i, '').trim();
if (txt.length > 600) txt = txt.slice(0, 600).trim();

// Nome so entra na mensagem se for nome de gente. O canal site preenche
// "Visitante do site" quando o lead nao se identificou.
const bruto = String(d.nome || '').trim();
const generico = /^(visitante|contato|cliente|lead|usuario|usuário)/i.test(bruto)
  || bruto.includes('@')
  || bruto === '';
const nome = generico ? '' : bruto.split(/\s+/)[0];
const oi = nome ? 'Oi, ' + nome + '!' : 'Oi!';

if (!txt) {
  const reserva = {
    1: oi + ' Voltando aqui rapidinho — quer continuar de onde a gente parou?',
    2: oi + ' Imagino que o dia esteja corrido. Quer que eu já passe sua busca para um corretor?',
    3: oi + ' Vou parar de escrever para não encher sua caixa 😊 Se voltar a procurar imóvel, é só me chamar por aqui.',
  };
  txt = reserva[d.etapa] || reserva[3];
}

return [{ json: { ...d, mensagem: txt, gerado_por_ia: !!String($json.output ?? '').trim() } }];

